def native_chain_rename(value):
    if isinstance(value,dict):
        return {key:native_chain_rename(entry)for key,entry in value.items()}
    if isinstance(value,list):
        return [native_chain_rename(entry)for entry in value]
    return "minecraft:iron_chain" if value=="minecraft:chain" else value

def sync(g):
    find,write_json=g["find"],g["write_json"]
    for name in RECIPES:
        relative="data/create/recipe/"+name
        data=with_native_conditions(json.loads(find(relative).read_text()))
        write_json(relative,g["modern_ingredients"](native_chain_rename(data)))
    for name in ADVANCEMENTS:
        relative="data/create/advancement/"+name
        data=with_native_conditions(json.loads(find(relative).read_text()))
        write_json(relative,g["modern_advancement"](native_chain_rename(data)))
    return {"recipes":len(RECIPES),"recipe_advancements":len(ADVANCEMENTS),"runtime":"UNRUN"}

if __name__=="__main__":
    import sys
    sys.dont_write_bytecode=True
    import sync_assets
    sync(vars(sync_assets))
